INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('The AI Business Blueprint: Work Smarter with Automation', 'Raleigh - Success Startup Entrepreneurs', 'Founders & Startups', '## What if your online business could keep working when you’re not? Imagine having AI agents supporting your marketing, approved content', '## What if your online business could keep working when you’re not? Imagine having AI agents supporting your marketing, approved content being posted automatically to social media, leads being captured while you’re away, and an intelligent AI sales advisor helping website visitors find the right products. That’s what you’ll explore in **The AI-Built** **Business That Works While You Don’t**. This isn’t another webinar about learning dozens of AI tools. It’s a live look at how AI, automation, More info: https://www.meetup.com/raleigh-success-startup-entrepreneurs/events/316782373/', '2026-10-12T15:00:00-04:00', 'Online event', 'Online event', 'Raleigh', 'NC', '', 35.77, -78.64, 'Raleigh - Success Startup Entrepreneurs', 9, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/raleigh-success-startup-entrepreneurs/events/316782373/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Fix and Flip Series : Time Hacks', 'Real Estate Investors & Deal Makers Sacramento', 'Real Estate', 'MONDAY 5 PM PST 7 PM CST 8 PM EST [SIGN UP HERE](https://link.elitereimm.com/widget/form/wSbrsstjtpMx77vSSif7?am_id=debbie5574) Use CRM,', 'MONDAY 5 PM PST 7 PM CST 8 PM EST [SIGN UP HERE](https://link.elitereimm.com/widget/form/wSbrsstjtpMx77vSSif7?am_id=debbie5574) Use CRM, systems, automation, and AI to run flips more efficiently without letting every project take over your life. Fixing and flipping can become a full-time job fast. Contractors need answers. Materials need to be ordered. Draws need to be tracked. Budgets change. Inspections get scheduled. Properties need to be marketed. And somehow you are still supposed to find More info: https://www.meetup.com/real-estate-deal-makers-investors-sacramento-ca/events/316783008/', '2026-10-12T17:00:00-07:00', 'Online event', 'Online event', 'Sacramento', 'CA', '', 38.62, -121.38, 'Real Estate Investors & Deal Makers Sacramento', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/real-estate-deal-makers-investors-sacramento-ca/events/316783008/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('[Virtual] Simple Real Estate Strategies That Work (Fun, Free, & Gets You Paid!)', 'Real Estate Investors & Deal Makers Sacramento', 'Real Estate', '**Most real estate trainings are like bad lectures:** boring, overloaded with information, and leaving you feeling like you’ll need weeks', '**Most real estate trainings are like bad lectures:** boring, overloaded with information, and leaving you feeling like you’ll need weeks of prep just to get started (or worst of all, they just want to sell you their expensive course or coaching). **We decided to do the exact opposite**—and hundreds of agents now agree. Join us **LIVE (virtual) every Wednesday at 9:00 AM CST** for a zero-fluff, action-packed call where active, top-producing agents openly share exactly what’s working right More info: https://www.meetup.com/real-estate-deal-makers-investors-sacramento-ca/events/316694200/', '2026-10-14T07:00:00-07:00', 'Online event', 'Online event', 'Sacramento', 'CA', '', 38.62, -121.38, 'Real Estate Investors & Deal Makers Sacramento', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/real-estate-deal-makers-investors-sacramento-ca/events/316694200/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('RE-AI Advantage Lab: Turn AI Into Your Real Estate Advantage', 'Real Estate Investors & Deal Makers Sacramento', 'Real Estate', 'AI is changing what “work” looks like for real estate agents. Tasks that used to take hours can now take minutes. Marketing can be created', 'AI is changing what “work” looks like for real estate agents. Tasks that used to take hours can now take minutes. Marketing can be created faster. Follow up can be smarter. Content can be generated almost instantly. But most agents are still trying to figure out **how to actually use AI in their day-to-day business.** That is exactly what we will be exploring inside the **RE-AI Advantage Lab.** This weekly training is designed specifically for real estate agents who want to learn how to use AI More info: https://www.meetup.com/real-estate-deal-makers-investors-sacramento-ca/events/316695032/', '2026-10-14T08:00:00-07:00', 'Online event', 'Online event', 'Sacramento', 'CA', '', 38.62, -121.38, 'Real Estate Investors & Deal Makers Sacramento', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/real-estate-deal-makers-investors-sacramento-ca/events/316695032/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Real Estate Agent Virtual Coffee Mastermind', 'Real Estate Investors & Deal Makers Sacramento', 'Real Estate', 'Start your morning... with a coffee & friends from all over the country. Don''t miss out on our live (virtual) networking event every', 'Start your morning... with a coffee & friends from all over the country. Don''t miss out on our live (virtual) networking event every Thursday morning. It''s the perfect opportunity to build relationships with Realtors across the state and across the country (sometimes even on the other side of the world) that will serve your clients well when they need a referral. We have a short educational/informative presentation at the beginning of the meeting and then go into 3 or 4 person breakout rooms More info: https://www.meetup.com/real-estate-deal-makers-investors-sacramento-ca/events/316709463/', '2026-10-15T07:00:00-07:00', 'Online event', 'Online event', 'Sacramento', 'CA', '', 38.62, -121.38, 'Real Estate Investors & Deal Makers Sacramento', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/real-estate-deal-makers-investors-sacramento-ca/events/316709463/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('ONLINE: INSIDE A $100M MORTGAGE FUND: Q3 EARNINGS & WHY INVEST WITH US', 'Real Estate Investing: Free Education and Mentoring(Nashville)', 'Real Estate', 'Utilize our *Audited* Mortgage Fund and earn safe and consistent returns—without compromising liquidity—8.45% per year! Structured with a', 'Utilize our *Audited* Mortgage Fund and earn safe and consistent returns—without compromising liquidity—8.45% per year! Structured with a low $25,000 minimum and a mere 12 month commitment, our Fund is the perfect opportunity Marshall Reddick clients—including those leveraging a self-directed retirement account—to tap into the Residential Real Estate Private Credit Market. Since inception, over the past 6.5 years, we’ve slowly, strategically and organically grown on our march to $100M. The More info: https://www.meetup.com/real-estate-investing-free-education-mentoring-nashville/events/316356503/', '2026-10-28T20:00:00-05:00', 'Online event', 'Online event', 'Nashville', 'TN', '', 36.17, -86.78, 'Real Estate Investing: Free Education and Mentoring(Nashville)', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/real-estate-investing-free-education-mentoring-nashville/events/316356503/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
