INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('[Virtual] Simple Real Estate Strategies That Work (Fun, Free, & Gets You Paid!)', 'Smart Money Houston', 'Real Estate', '**Most real estate trainings are like bad lectures:** boring, overloaded with information, and leaving you feeling like you’ll need weeks', '**Most real estate trainings are like bad lectures:** boring, overloaded with information, and leaving you feeling like you’ll need weeks of prep just to get started (or worst of all, they just want to sell you their expensive course or coaching). **We decided to do the exact opposite**—and hundreds of agents now agree. Join us **LIVE (virtual) every Wednesday at 9:00 AM CST** for a zero-fluff, action-packed call where active, top-producing agents openly share exactly what’s working right More info: https://www.meetup.com/real-estate-realtor-houston/events/316694180/', '2026-10-14T09:00:00-05:00', 'Online event', 'Online event', 'Houston', 'TX', '', 29.78, -95.6, 'Smart Money Houston', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/real-estate-realtor-houston/events/316694180/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('RE-AI Advantage Lab: Turn AI Into Your Real Estate Advantage', 'Smart Money Houston', 'Real Estate', 'AI is changing what “work” looks like for real estate agents. Tasks that used to take hours can now take minutes. Marketing can be created', 'AI is changing what “work” looks like for real estate agents. Tasks that used to take hours can now take minutes. Marketing can be created faster. Follow up can be smarter. Content can be generated almost instantly. But most agents are still trying to figure out **how to actually use AI in their day-to-day business.** That is exactly what we will be exploring inside the **RE-AI Advantage Lab.** This weekly training is designed specifically for real estate agents who want to learn how to use AI More info: https://www.meetup.com/real-estate-realtor-houston/events/316695057/', '2026-10-14T10:00:00-05:00', 'Online event', 'Online event', 'Houston', 'TX', '', 29.78, -95.6, 'Smart Money Houston', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/real-estate-realtor-houston/events/316695057/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Real Estate Agent Virtual Coffee Mastermind', 'Smart Money Houston', 'Real Estate', '**Start your morning...** with a coffee & friends from all over the country. Don''t miss out on our live (virtual) networking event every', '**Start your morning...** with a coffee & friends from all over the country. Don''t miss out on our live (virtual) networking event every Thursday morning. It''s the perfect opportunity to build relationships with Realtors across the state and across the country (sometimes even on the other side of the world) that will serve your clients well when they need a referral. We have a short educational/informative presentation at the beginning of the meeting and then go into 3 or 4 person breakout More info: https://www.meetup.com/real-estate-realtor-houston/events/316709268/', '2026-10-15T09:00:00-05:00', 'Online event', 'Online event', 'Houston', 'TX', '', 29.78, -95.6, 'Smart Money Houston', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/real-estate-realtor-houston/events/316709268/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Part-Time Investing for Full-Time Income', 'Real Estate Shark Tank- Philadelphia by Investor Schooling', 'Real Estate', 'Right now is the time to start your investment strategy plan for this changing world. Our Thursday class starts at 7 pm sharp at our', 'Right now is the time to start your investment strategy plan for this changing world. Our Thursday class starts at 7 pm sharp at our Langhorne office or online. Here’s the address for the office again: 108 Corporate Dr E Langhorne, PA 19047 Try to be there around 6:45 pm so you have time to chat and such before we get started. Or ... Join us from the safety of your home. For either one please register at: [https://investorschooling.com/rsvp](https://investorschooling.com/rsvp) If you want to More info: https://www.meetup.com/real-estate-shark-tank-philadelphia/events/316909246/', '2026-10-15T19:00:00-04:00', 'Investor Schooling', '108 Corporate Dr E', 'Langhorne', 'PA', '', 40, -75.14, 'Real Estate Shark Tank- Philadelphia by Investor Schooling', 1, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/real-estate-shark-tank-philadelphia/events/316909246/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
